class Solution:
    def pathInZigZagTree(self, label: int) -> List[int]:
        res = []
        while label >= 1:
            res.append(label)
            d = label.bit_length() - 1
            if d % 2 == 1:
                label = (1 << d) + (1 << (d + 1)) - 1 - label
            label //= 2
            nd = label.bit_length() - 1
            if label > 1 and nd % 2 == 1:
                label = (1 << nd) + (1 << (nd + 1)) - 1 - label
        return res[::-1]

