class Solution {
public:
    vector<int> pathInZigZagTree(int label) {
        vector<int> res;
        while (label >= 1) {
            res.push_back(label);
            int d = 31 - __builtin_clz(label);
            if (d % 2 == 1)
                label = (1 << d) + (1 << (d + 1)) - 1 - label;
            label /= 2;
            int nd = 31 - __builtin_clz(max(label, 1));
            if (label > 1 && nd % 2 == 1)
                label = (1 << nd) + (1 << (nd + 1)) - 1 - label;
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

