        res.push(label);
        let d = Math.floor(Math.log2(label));
        if (d % 2 === 1)
            label = (1 << d) + (1 << (d + 1)) - 1 - label;
        label = Math.floor(label / 2);
        let nd = label > 0 ? Math.floor(Math.log2(label)) : 0;
        if (label > 1 && nd % 2 === 1)
            label = (1 << nd) + (1 << (nd + 1)) - 1 - label;
    }
    return res.reverse();
};

